import static org.junit.Assert.*;
import java.io.StringReader;

public class JjFillTokenTests {

    private SimpleCharStream streamFromString(String s) throws Exception {
        // Attempt to construct SimpleCharStream with common JavaCC constructors
        // Prefer (Reader, int, int)
        try {
            return new SimpleCharStream(new StringReader(s), 1, 1);
        } catch (NoSuchMethodError | UnsatisfiedLinkError | ExceptionInInitializerError ignore) {
            // Fallback to (Reader)
        }

        try {
            return new SimpleCharStream(new StringReader(s));
        } catch (NoSuchMethodError ignore) {
            // If neither constructor is available, rethrow to fail the test setup
        }

        // As a last resort, try a constructor with (Reader, int, int) via reflection if needed
        try {
            Class<?> cls = Class.forName("org.apache.commons.jxpath.ri.parser.SimpleCharStream");
            return (SimpleCharStream) cls.getConstructor(StringReader.class).newInstance(new StringReader(s));
        } catch (Exception e) {
            throw new RuntimeException("Could not instantiate SimpleCharStream for test", e);
        }
    }

    @Test
    public void testFillToken_UsesStreamImageWhenLiteralNull() throws Exception {
        SimpleCharStream stream = streamFromString("A");
        XPathParserTokenManager manager = new XPathParserTokenManager(stream);

        // jjstrLiteralImages[1] is null according to provided array
        manager.jjmatchedKind = 1;

        Token t = manager.jjFillToken();

        assertNotNull("Token should not be null", t);
        assertEquals("Token kind should match jjmatchedKind", 1, t.kind);
        // Since literal image for kind 1 is null, image should come from stream.GetImage()
        assertEquals("Image should come from stream when literal image is null",
                stream.GetImage(), t.image);

        assertEquals("Begin line should match stream", stream.getBeginLine(), t.beginLine);
        assertEquals("Begin column should match stream", stream.getBeginColumn(), t.beginColumn);
        assertEquals("End line should match stream", stream.getEndLine(), t.endLine);
        assertEquals("End column should match stream", stream.getEndColumn(), t.endColumn);
    }

