        assertNotNull("Token should not be null", t);
        assertEquals("Token kind should match jjmatchedKind", 6, t.kind);
        // There is a literal image for kind 6
        assertEquals("Token image should be the literal image for kind 6", "\\57", t.image);

        assertEquals("Begin line should match stream", stream.getBeginLine(), t.beginLine);
